import{c as t,Q as a,j as i,m as o}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Sovereign Agentic Loops: Decoupling AI Reasoning from Execution in Real-World Systems","description":"","frontmatter":{"url":"https://arxiv.org/abs/2604.22136","title":"Sovereign Agentic Loops: Decoupling AI Reasoning from Execution in Real-World Systems","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2604.22136,"authors":["Jun He","Deying Yu"],"domains":["cs.CR"],"html":"https://arxiv.org/html/2604.22136v1","pdf_path":"pdfs/2604.22136.pdf","published_date":"2026-04-24T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-04-24-sovereign-agentic-loops-decoupling-reasoning-execution-2604-22136.md","filePath":"research/papers/2026-04-24-sovereign-agentic-loops-decoupling-reasoning-execution-2604-22136.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-04-24-sovereign-agentic-loops-decoupling-reasoning-execution-2604-22136.md"};function r(s,e,l,c,d,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="sovereign-agentic-loops-decoupling-ai-reasoning-from-execution-in-real-world-systems" tabindex="-1">Sovereign Agentic Loops: Decoupling AI Reasoning from Execution in Real-World Systems <a class="header-anchor" href="#sovereign-agentic-loops-decoupling-ai-reasoning-from-execution-in-real-world-systems" aria-label="Permalink to &quot;Sovereign Agentic Loops: Decoupling AI Reasoning from Execution in Real-World Systems&quot;">​</a></h1><p><strong>Authors</strong>: Jun He, Deying Yu <strong>Published</strong>: April 24, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2604.22136" target="_blank" rel="noreferrer">https://arxiv.org/abs/2604.22136</a> · <a href="https://arxiv.org/html/2604.22136v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2604.22136 <strong>Categories</strong>: cs.CR <strong>PDF</strong>: <a href="https://arxiv.org/abs/2604.22136" target="_blank" rel="noreferrer">research/papers/pdfs/2604.22136.pdf</a> (15 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Large language model (LLM) agents increasingly issue API calls that mutate real systems, yet many current architectures pass stochastic model outputs directly to execution layers. We argue that this coupling creates a safety risk because model correctness, context awareness, and alignment cannot be assumed at execution time. We introduce Sovereign Agentic Loops (SAL), a control-plane architecture in which models emit structured intents with justifications, and the control plane validates those intents against true system state and policy before execution. SAL combines an obfuscation membrane, which limits model access to identity-sensitive state, with a cryptographically linked Evidence Chain for auditability and replay. We formalize SAL and show that, under the stated assumptions, it provides policy-bounded execution, identity isolation, and deterministic replay. In an OpenKedge prototype for cloud infrastructure, SAL blocks 93% of unsafe intents at the policy layer, rejects the remaining 7% via consistency checks, prevents unsafe executions in our benchmark, and adds 12.4 ms median latency.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 <strong>Sovereign Agentic Loops (SAL)</strong>：一種 control-plane 架構，將 LLM 的 reasoning 與 execution 解耦——模型只發出帶 justification 的 structured intent，由 control plane 對照真實系統狀態與 policy 驗證後才執行。</li><li>引入 <strong>obfuscation membrane</strong>：限制模型對 identity-sensitive state 的存取，達成 identity isolation。</li><li>引入 <strong>cryptographically linked Evidence Chain</strong>：提供 auditability 與 deterministic replay 能力。</li><li>形式化 SAL，並證明在所述假設下可提供三項性質：policy-bounded execution、identity isolation、deterministic replay。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>OpenKedge 雲端基礎設施 prototype 中，SAL 在 policy layer 攔截 <strong>93%</strong> 的 unsafe intent。</li><li>剩餘 <strong>7%</strong> 由 consistency check 拒絕。</li><li>benchmark 中阻止了全部 unsafe execution。</li><li>中位延遲增加 <strong>12.4 ms</strong>（median latency overhead）。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><p>文件未列明確 limitation 章節（依 abstract 推斷）。判斷的弱點：</p><ul><li>安全保證明確標注「under the stated assumptions」——若 policy 完整性、true system state 取得正確性等前提不成立，保證即失效；abstract 未揭露假設破裂時的退化行為。</li><li>評估僅單一 OpenKedge prototype + 自建 benchmark，缺跨域 / 對抗性 intent 泛化證據；93/7 的攔截分布可能對 benchmark 構造敏感。</li><li>12.4 ms 為 median，未報 tail latency（p99）；high-throughput control plane 下的吞吐影響未知。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>直接呼應「判斷 vs 決定」鐵律</strong>（core.md 跨切紀律）：SAL 的 model-emits-intent / control-plane-decides 切分，正是「LLM 只做判斷、確定性代碼做決定（路由/HTTP status/數學）」的架構化實作；可作為該規則的外部 prior art 佐證。⚠️ 落地門檻：本 workspace 的閘門靠 hooks + 機械驗證，非 abstract 中的 formal control plane，等價性需驗。</li><li><strong>對應 The Loop 的 APPLY 破壞性 gate 與生產紅線</strong>：SAL「intent → policy 驗證 → 才 execute」與 core.md「prod apply/delete 先 plan/diff 再二次確認」「不可逆動作必顯摘要等確認」同構；可借其 Evidence Chain 概念強化 unverified_success 閘門的 auditability。</li><li><strong><code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）的 unverified verdict 紀律</strong>：SAL 強調 model 輸出在 execution 前不可信，與「subagent/workflow verdict 非證據，採信前機械 grep 重驗」一致；SAL 的 deterministic replay 可類比主對話親跑確定性檢查。</li><li>⚠️ 整體屬 cs.CR 架構論文（off-rails 落地風險）：把 SAL 概念套到本 workspace 需顯式 spec，不可靜默移植；其安全保證受假設約束，無現成檔案路徑可直接對接。</li></ul>',17)])])}const h=t(n,[["render",r]]);export{g as __pageData,h as default};
